'use strict';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal'),KEY='buklabs-mal-game-v1',PREF='buklabs-mal-settings-v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(k){try{return JSON.parse(localStorage.getItem(k));}catch{return null;}}
function write(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch{}}
let prefs={mode:'Jugadores',category:'Todas',seconds:30,rounds:3,sound:true,...read(PREF)},names=['Jugador 1','Jugador 2'],view='setup',game=new MalEngine(RevesQuestions),saved=read(KEY),audio,toastTimer,lastSecond,lastAction=0;
if(!saved||saved.version!==1||!Array.isArray(saved.players)||saved.players.length<2||!Array.isArray(saved.deck)||!saved.deck.length||saved.deck.some(id=>!RevesQuestions.some(q=>q.id===id)))saved=null;
if(saved?.phase==='running'){saved.phase='paused';saved.deadline=null;saved.questionDeadline=null;}
function save(){saved=game.s;write(KEY,saved);}
function notify(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),1700);}
function beep(good){if(!prefs.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),v=audio.createGain();o.connect(v);v.connect(audio.destination);o.frequency.value=good?660:220;v.gain.setValueAtTime(.05,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.14);o.start();o.stop(audio.currentTime+.15);}catch{}}
function header(){return `<header class="header"><button class="brand" data-action="home" aria-label="MAL., inicio"><img class="game-wordmark" src="../../assets/mal-logo.png" alt="MAL." width="2048" height="682"></button><div class="nav">${view==='game'&&game.s?.phase==='running'?'<button class="icon-btn" data-action="pause" aria-label="Pausar">Ⅱ</button>':'<button class="ghost" data-action="help">Cómo jugar ↗</button>'}<button class="icon-btn" data-action="sound" aria-label="${prefs.sound?'Silenciar':'Activar'} sonido" aria-pressed="${prefs.sound}">${prefs.sound?'♪':'♫̸'}</button></div></header>`;}
function chips(key,values){return `<div class="segments">${values.map(([v,t])=>`<button class="chip ${String(prefs[key])===String(v)?'selected':''}" data-action="setting" data-key="${key}" data-value="${v}" aria-pressed="${String(prefs[key])===String(v)}">${t}</button>`).join('')}</div>`;}
function setup(){return `${saved&&saved.phase!=='over'?'<div class="resume-banner"><span>Hay una partida pendiente.</span><button data-action="resume-saved">Continuar →</button></div>':''}<section class="intro"><div><div class="eyebrow">EL JUEGO DE RESPONDER INCORRECTAMENTE</div><h1>Responde mal.<br>Gana <em>bien.</em></h1><p>Sabes la respuesta. Ese es el problema.<br>Tienes tres segundos para decir cualquier cosa… menos la verdad.</p></div><div class="art" aria-hidden="true"><div class="question-card"><small>AQUÍ EQUIVOCARSE SUMA</small><strong>5 + 5 = <span>10</span></strong><b>2 ✓</b></div></div></section><div class="layout"><section class="panel"><h2>01 &nbsp; ¿Quién se equivoca mejor?</h2>${chips('mode',[['Jugadores','Por jugador'],['Equipos','Por equipo']])}<p class="note">${prefs.mode==='Equipos'?'Un representante responde en cada turno; roten entre integrantes.':'El siguiente jugador lee las preguntas. Los puntos son para quien responde.'}</p><form class="add" id="add-form"><input id="name" placeholder="${prefs.mode==='Equipos'?'Nombre del equipo':'Nombre del jugador'}" aria-label="Nombre del participante" maxlength="35" autocomplete="off"><button type="submit" aria-label="Agregar">+</button></form><ul class="players">${names.map((n,i)=>`<li><b>${String(i+1).padStart(2,'0')}</b><span>${esc(n)}</span><button class="remove" data-action="remove" data-index="${i}" aria-label="Quitar ${esc(n)}">×</button></li>`).join('')}</ul><p class="note">Mínimo 2 participantes, sin límite fijo.</p></section><section class="panel"><h2>02 &nbsp; Dale ritmo</h2><label class="label" for="category">Preguntas</label><select id="category"><option>Todas</option>${[...new Set(RevesQuestions.map(q=>q.category))].map(c=>`<option ${prefs.category===c?'selected':''}>${c}</option>`).join('')}</select><span class="label">Segundos por turno</span>${chips('seconds',[[30,'30 s · rápido'],[45,'45 s'],[60,'60 s']])}<span class="label">Turnos por participante</span>${chips('rounds',[[1,'1'],[3,'3'],[5,'5']])}<div class="summary">Respuesta incorrecta <b>+1</b> · Verdadera <b>0</b><br>Tienes <b>3 segundos</b> desde que el lector toca «Ya leí». El reloj del turno también corre durante la lectura.</div></section></div><div class="start-row"><p class="note">${RevesQuestions.filter(q=>prefs.category==='Todas'||q.category===prefs.category).length} preguntas en tu selección · ${names.length*prefs.rounds} turnos</p><button class="primary" data-action="create" ${names.length<2?'disabled':''}>Vamos a hacerlo mal <span>→</span></button></div>`;}
function scores(){return `<div class="score-chips">${game.s.players.map(p=>`<span>${esc(p.name)} <b>${p.score}</b></span>`).join('')}</div>`;}
function ready(){const s=game.s,reader=s.players[(s.turn+1)%s.players.length].name;return `<section class="turn"><div class="round-icon">↔</div><div class="eyebrow">RONDA ${game.round} DE ${s.config.rounds}</div><p>Responde</p><h1>${esc(game.player.name)}</h1><p>${s.config.mode==='Equipos'?'Alguien de':'Lee'} <strong>${esc(reader)}</strong>.<br>Quien responde no mira la pantalla.</p><p>${s.config.seconds} segundos de turno.<br>3 segundos por respuesta. No repitas respuestas.</p><button class="primary" data-action="start">Listo, primera pregunta →</button>${scores()}</section>`;}
function playing(){const s=game.s,q=game.question,answering=s.stage==='answering';return `<section class="game"><div class="game-top"><span class="name">${esc(game.player.name)} · ronda ${game.round}/${s.config.rounds}</span><span class="global-time" id="global-time">${Math.ceil(s.remaining/1000)}s</span></div><div class="track"><i id="track" style="width:${s.remaining/(s.config.seconds*10)}%"></i></div><div class="prompt-card"><div class="eyebrow">${answering?'RESPONDE MAL. AHORA.':'LEE LA PREGUNTA EN VOZ ALTA'}</div><h1>${esc(q.question)}</h1><div class="expected">Respuesta verdadera: <strong>${esc(q.answer)}</strong></div></div>${answering?`<div class="response-clock"><span>Tiempo para responder</span><b id="response-time">${(s.questionRemaining/1000).toFixed(1)}s</b></div><div class="answers"><button class="secondary" data-action="truth">Dijo la verdad<span>0 PUNTOS</span></button><button class="primary" data-action="wrong">¡Incorrecta!<span>+1 PUNTO</span></button></div>`:'<button class="primary listen" data-action="listen">Ya leí · escuchar respuesta <span>3s →</span></button>'}<div class="bottom"><button class="ghost" data-action="skip">Pasar / no válida · 0 pts</button><span class="note">${answering?'Sin repetir respuestas. El lector valida.':'Toca «Ya leí» al terminar de preguntar.'}</span></div></section>`;}
function paused(){return `<section class="turn"><div class="round-icon">Ⅱ</div><div class="eyebrow">PAUSA</div><h1>Respira.<br>Pero no pienses.</h1><p>Los relojes están detenidos.<br>Devuelve el dispositivo a quien lee.</p><button class="primary" data-action="unpause">Continuar →</button><button class="ghost" data-action="home">Guardar y volver al inicio</button></section>`;}
function result(){const h=game.s.history.at(-1),last=game.s.turn+1>=game.s.players.length*game.s.config.rounds;return `<section class="turn"><div class="eyebrow">SE ACABÓ EL TURNO</div><div class="result-score">+${h.points}</div><h2>${esc(h.player)}</h2><p>${h.points===1?'Una respuesta incorrecta.':h.points+' respuestas incorrectas.'}<br>${h.points?'Nada mal. O, mejor dicho, muy mal.':'La próxima vez, menos verdades.'}</p><button class="primary" data-action="next">${last?'Ver resultados':'Siguiente turno'} →</button>${scores()}<details class="log"><summary>Ver las ${h.events.length} preguntas respondidas</summary>${h.events.map(e=>`<p>${esc(e.question)} <b>+${e.points}</b></p>`).join('')}</details></section>`;}
function over(){const rows=[...game.s.players].sort((a,b)=>b.score-a.score),win=rows.filter(p=>p.score===rows[0].score);return `<section class="over"><div class="eyebrow">CREADO POR BUKLABS · FIN DE PARTIDA</div><h1>Lo hicieron muy MAL.</h1><p>${win.length>1?'Empate entre '+win.map(p=>esc(p.name)).join(', '):esc(win[0].name)+' se lleva la victoria.'}</p><ol class="leaderboard">${rows.map((p,i)=>`<li><span class="rank">${i===0?'★':i+1}</span><span class="name">${esc(p.name)}</span><strong>${p.score} <small>PTS</small></strong></li>`).join('')}</ol><div class="buttons"><button class="primary" data-action="rematch">Otra partida ↻</button><button class="secondary" data-action="edit">Cambiar participantes</button></div><details class="log"><summary>Ver todos los turnos</summary>${game.s.history.map(h=>`<p>Ronda ${h.round} · ${esc(h.player)} · <b>+${h.points}</b></p>`).join('')}</details></section>`;}
function render(){document.body.dataset.play=String(view==='game'&&['running','paused'].includes(game.s?.phase));const content=view==='setup'?setup():game.s.phase==='ready'?ready():game.s.phase==='running'?playing():game.s.phase==='paused'?paused():game.s.phase==='result'?result():over();app.innerHTML=`<main class="wrap">${header()}${content}<footer class="footer"><span>Creado por BUKLABS</span><button class="ghost" data-buk="install">Instalar BUKLABS Play ↗</button></footer></main>`;}
function create(){game=new MalEngine(RevesQuestions);game.create(names,prefs);save();view='game';render();scrollTo(0,0);}
function help(){modal.innerHTML='<h2>Equivocarse<br>es el objetivo.</h2><ol><li>Una persona lee y otra responde sin mirar la pantalla.</li><li>Al terminar de leer, toca <strong>Ya leí</strong>. Empiezan los tres segundos para responder.</li><li>Si la respuesta es incorrecta, pulsa <strong>¡Incorrecta! +1</strong>. Si dijo la verdad, marca cero.</li><li>Si se queda callado, dice «no sé» o repite una respuesta, marca <strong>Pasar / no válida</strong>. Si supera tres segundos, la pregunta cambia automáticamente y no suma.</li></ol><p>La respuesta debe contestar a la pregunta. No tiene que ser graciosa. Acepten cualquier respuesta verdadera equivalente a la referencia: esa respuesta no suma.</p><p>Los 30 segundos del turno incluyen la lectura. El siguiente jugador será el lector. Nadie queda eliminado.</p><button class="primary" data-action="close">Entendido</button>';modal.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
 if(['listen','wrong','truth','skip'].includes(action)){const now=Date.now();if(now-lastAction<180)return;lastAction=now;}
 switch(action){
 case 'home':if(game.s?.phase==='running')game.pause();if(game.s)save();view='setup';render();scrollTo(0,0);break;
 case 'help':help();break;
 case 'close':modal.close();break;
 case 'sound':prefs.sound=!prefs.sound;write(PREF,prefs);render();break;
 case 'setting':{const k=b.dataset.key,v=b.dataset.value;if(k==='mode'&&v!==prefs.mode){const prev=prefs.mode==='Equipos'?'Equipo':'Jugador',next=v==='Equipos'?'Equipo':'Jugador';names=names.map((n,i)=>n===`${prev} ${i+1}`?`${next} ${i+1}`:n);}prefs[k]=['seconds','rounds'].includes(k)?Number(v):v;write(PREF,prefs);render();break;}
 case 'remove':names.splice(Number(b.dataset.index),1);render();break;
 case 'create':if(saved&&saved.phase!=='over'){modal.innerHTML='<h2>¿Nueva partida?</h2><p>Se reemplazará la partida pendiente por una nueva con esta configuración.</p><button class="primary" data-action="confirm-create">Empezar nueva partida</button><button class="secondary" data-action="close">Volver</button>';modal.showModal();}else create();break;
 case 'confirm-create':modal.close();create();break;
 case 'resume-saved':game=new MalEngine(RevesQuestions,saved);view='game';render();break;
 case 'start':game.start();save();render();scrollTo(0,0);beep(true);break;
 case 'listen':game.listen();save();render();break;
 case 'wrong':if(game.answer(true))beep(true);save();render();break;
 case 'truth':game.answer(false);save();render();break;
 case 'skip':game.skip();save();render();break;
 case 'pause':game.pause();save();render();break;
 case 'unpause':game.resume();save();render();break;
 case 'next':game.next();save();render();scrollTo(0,0);break;
 case 'rematch':names=game.s.players.map(p=>p.name);prefs={...prefs,...game.s.config};create();break;
 case 'edit':names=game.s.players.map(p=>p.name);prefs={...prefs,...game.s.config};view='setup';render();scrollTo(0,0);break;
 }
});
document.addEventListener('submit',e=>{if(e.target.id!=='add-form')return;e.preventDefault();const name=$('#name').value.trim();if(!name)return;if(names.some(n=>n.toLowerCase()===name.toLowerCase())){notify('Ese nombre ya está en la partida.');return;}names.push(name);render();$('#name').focus();});
document.addEventListener('change',e=>{if(e.target.id==='category'){prefs.category=e.target.value;write(PREF,prefs);render();}});
setInterval(()=>{if(view!=='game'||game.s?.phase!=='running')return;const event=game.tick();if(event){beep(false);save();render();if(event==='question')notify('Tiempo agotado · siguiente pregunta');return;}const s=game.s,sec=Math.ceil(s.remaining/1000),timer=$('#global-time');if(timer){timer.textContent=sec+'s';timer.classList.toggle('urgent',sec<=5);}const track=$('#track');if(track)track.style.width=s.remaining/(s.config.seconds*10)+'%';const response=$('#response-time');if(response)response.textContent=(s.questionRemaining/1000).toFixed(1)+'s';if(lastSecond!==sec){lastSecond=sec;save();}},80);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.s?.phase==='running'){game.pause();save();render();}});
window.addEventListener('pagehide',()=>{if(game.s?.phase==='running')game.pause();if(game.s)save();});
window.addEventListener('buk:installing',()=>{if(game.s?.phase==='running'){game.pause();save();render();}});
render();

window.addEventListener('pageshow',event=>{if(event.persisted)render();});
